import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/ON.DXVlsWbj.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as r,a as s}from"./chunks/M-S-GMc.LRrwxYc0.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as l,o as n,c as m,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const B=JSON.parse('{"title":"Glucometro","description":"","frontmatter":{"source_hash":"ec52e7eb65","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/use/glucometer.md","filePath":"it/use/glucometer.md"}'),p={name:"it/use/glucometer.md"};function u(d,o,g,h,_,v){return n(),m("div",null,[...o[0]||(o[0]=[c('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_touch_app_grey600_48dp.png" style="width:5%;"> Glucometri</p></div><br><h5 id="nfc-meter" tabindex="-1">Glucometro NFC <a class="header-anchor" href="#nfc-meter" aria-label="Permalink to &quot;Glucometro NFC {#nfc-meter}&quot;">​</a></h5><p>Se usi un glucometro Glucomen Aero con un telefono dotato di lettore NFC, puoi scansionarlo per ottenere l&#39;ultima lettura.</p><div class="admonition xdripitem"><p class="admonition-title">Usa Glucometro NFC <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Scarica le letture dal glucometro NFC quando xDrip è aperto</p></div><h5 id="if-you-use-a-compatible-bluetooth-meter" tabindex="-1">Se usi un glucometro Bluetooth compatibile <a class="header-anchor" href="#if-you-use-a-compatible-bluetooth-meter" aria-label="Permalink to &quot;Se usi un glucometro Bluetooth compatibile {#if-you-use-a-compatible-bluetooth-meter}&quot;">​</a></h5><p>Per attivare Usa un glucometro Bluetooth devi prima associare un glucometro Bluetooth.<br> Se il glucometro è nuovo, <strong>assicurati di aver misurato la glicemia almeno una volta prima di provare ad associarlo</strong>.</p><p><strong><u>Non</u></strong> attivare per ora l&#39;opzione del glucometro Bluetooth in xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Usa un glucometro Bluetooth <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Connettersi e caricare automaticamente i dati da un glucometro compatibile come il Contour Next One</p></div><p>Cerca il glucometro Bluetooth:</p><div class="admonition xdripitem"><p class="admonition-title">Scansiona il glucometro Bluetooth</p></div><p>Metti il glucometro in modalità di associazione e tocca scansiona nel menu Scansiona il glucometro Bluetooth.</p><img src="'+r+'" style="zoom:75%;"><img src="'+s+'" style="zoom:75%;"><p>Una volta associato, puoi attivare il glucometro nel menu.</p><div class="admonition xdripitem"><p class="admonition-title">Usa un glucometro Bluetooth <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Connettersi e caricare automaticamente i dati da un glucometro compatibile come il Contour Next One</p></div><p>Il tuo glucometro verrà ora mostrato qui sotto:</p><div class="admonition xdripitem"><p class="admonition-title">Scansiona il glucometro Bluetooth</p><p> Bayer HealthCare LLC AA:BB:CC:DD:EE:FF:00</p></div><p>Puoi attivare dei suoni che indicano connessione, disconnessione e raccolta dei dati.</p><div class="admonition xdripitem"><p class="admonition-title">Indicatori sonori</p><p> Abilita questa opzione per avere avvisi sonori quando il glucometro si connette, disconnette o sincronizza i dati</p></div><p>Puoi far sì che xDrip ti proponga di usare il risultato per calibrare il sensore connesso (se supporta la calibrazione).</p><div class="admonition xdripitem"><p class="admonition-title">Usa il glucometro per calibrare <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Quando viene ricevuta una nuova misura capillare chiedi se deve essere utilizzata per calibrare</p></div><p>Non è consigliato attivare la calibrazione automatica.</p><div class="admonition xdripitem"><p class="admonition-title">Calibrazione automatica <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Calibra automaticamente utilizzando le letture di glicemia se le condizioni sembrano giuste, senza chiedere conferma (sperimentale)</p></div><p>Quando attivi l&#39;uso del glucometro Bluetooth, tutte le misure capillari verranno trasferite automaticamente in xDrip come <a href="./mainUI.html#treatments">trattamenti</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2022.05.04" target="_blank" rel="noreferrer"><em>Ultima modifica 4/5/2022</em></a></p>',27)])])}const N=l(p,[["render",u]]);export{B as __pageData,N as default};
